int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // If the current frame is null, create a new one with the given parameters.
    if (currentFrame == null) {
        currentFrame = new StackMapFrame(offset, numLocal, numStack);
        return 0;
    }

    // If the current frame is not null, ensure that the bytecode offset is consistent and that
    // the number of local and stack elements is greater than the previous frame.
    if (currentFrame.offset != offset) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    if (currentFrame.numLocals != numLocal) {
        throw new IllegalArgumentException("Invalid number of local variables: " + numLocal);
    }
    if (currentFrame.numStack != numStack) {
        throw new IllegalArgumentException("Invalid number of stack elements: " + numStack);
    }

    // If all checks pass, increment the current stack map frame and return the index of the next
    // element to be written in this frame.
    currentFrame = currentFrame.next;
