    if (target.isEmpty()) {
        throw new IllegalArgumentException("The target graph must not be empty");
    }

    // Get the set of vertices in the target graph
    Set<V> vertices = target.vertexSet();

    // Check if the result map is empty
    if (resultMap.isEmpty()) {
        throw new IllegalArgumentException("The result map must not be empty");
    }

    // Check if the result map has the same number of vertices as the target graph
    if (resultMap.size() != vertices.size()) {
        throw new IllegalArgumentException("The result map must have the same number of vertices as the target graph");
    }

    // Iterate over each vertex in the target graph
    for (V vertex : vertices) {
        // Add the current vertex to the result map
        resultMap.put(vertex, new HashSet<>());

        // Iterate over each vertex in the target graph
        for (V neighbor : vertices) {
            // Check if the current vertex is equal to the neighbor vertex
            if (vertex.equals(neighbor)) {
                // Skip current neighbor and continue iteration
                continue;
            }

            // Check if the current vertex has a neighbor edge to the neighbor vertex
            if (target.getEdge(vertex, neighbor) == null) {
                // Add a new edge between the current vertex and the neighbor vertex
                target.addEdge(vertex, neighbor, new DefaultEdge());

                // Add the neighbor vertex to the result map
                resultMap.get(vertex).add(neighbor);
