    if (target == null) {
        throw new NullPointerException("Target graph cannot be null.");
    }

    // Check if the result map is not null
    if (resultMap == null) {
        throw new NullPointerException("Result map cannot be null.");
    }

    // Create a new graph with the same vertex and edge types as the target graph
    Graph<V, E> newGraph = new Graph<>(target.getVertexSupplier(), target.getEdgeSupplier());

    // Add all vertices to the new graph
    for (V vertex : target.vertexSet()) {
        newGraph.addVertex(vertex);
    }

    // Add all edges to the new graph
    for (E edge : target.edgeSet()) {
        newGraph.addEdge(edge.getSource(), edge.getTarget(), edge);
    }

    // Copy the result map to the new graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        newGraph.addVertex(vertex);
        newGraph.addVertex(entry.getKey(), vertex);
    }

    // Return the new graph
    target = newGraph;
