 * Resolves the arguments for the {@code genericType} using the type variable information for the {@code targetType}.
 * Returns {@code null} if {@code genericType} is not parameterized or if arguments cannot be resolved.
 */
public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if genericType is not parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Check if targetType is assignable to the raw type of genericType
    if (!(targetType.isAssignableFrom(((ParameterizedType) genericType).getRawType()))) {
        return null;
    }

    Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Check if actualTypeArguments is null or empty
    if ((actualTypeArguments == null) || (actualTypeArguments.length == 0)) {
        return null;
    }

    // Get a Types instance from the targetType object
    Types types = Types.getTypes(targetType);

    // Create a new Class<?> array for the resolvedTypes
    Class<?>[] resolvedTypes = new Class<?>[actualTypeArguments.length];

    // Iterate over the actualTypeArguments and resolve the types
    for (int i = 0; i < actualTypeArguments.length; i++) {
        // Get the actual type argument
        Type actualTypeArgument = actualTypeArguments[i];

        // Check if the actual type is a wildcard
        if (actualTypeArgument instanceof WildcardType) {
            // Get the upper bound of the wildcard type
            Type upperBound = ((WildcardType) actualTypeArgument).getUpperBounds()[0];

            // Resolve the upper bound type using the types object
            resolvedTypes[i] = types.resolve(upperBound);
        } else {
            // Resolve the actual type using the types object
            resolvedTypes[i] = types.resolve(actualTypeArgument);
        }
    }

    return resolvedTypes;
}

