public List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Duration exceeds maximum fetch data duration");
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    long remainingTime = duration;
    while (remainingTime > 0) {
        long rangeStart = start + (duration - remainingTime);
        long rangeEnd = start + (duration - remainingTime) + FETCH_DATA_DURATION;
        if (rangeEnd > end) {
            rangeEnd = end;
        }
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
        remainingTime -= FETCH_DATA_DURATION;
    }
    return timeRanges;
}

/**
 * Split time ranges to insure the start time and end time is small then {@link #FETCH_DATA_DURATION}
 *
 * @param start the start time
 * @param end the end time
 * @return a list of time ranges
 */
private List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end || end > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Invalid start and end time");
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end && start < FETCH_DATA_DURATION) {
        long endTime = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, endTime));
        start = endTime;
    }
    return timeRanges;
}

