    List<TimeRange> timeRanges = new ArrayList<>();

    while (start < end) {
        long duration = Math.min(end - start, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(start, start + duration));
        start += duration;
    }

    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    if (start >= FETCH_DATA_DURATION || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Start time and end time must be less than or equal to fetch data duration.");
    }

    long currentStart = start, currentEnd = currentStart + FETCH_DATA_DURATION - 1;
    while (currentEnd < end) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
        currentEnd = currentStart + FETCH_DATA_DURATION - 1;
    }

    if (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, end));
    }

    return timeRanges;
}

