private static String substituteVar(String value, Properties props) {
String result = value;
Pattern VAR_PATTERN = Pattern.compile("\\$\\{([a-zA-Z0-9_-]+)\\}");
Matcher matcher = VAR_PATTERN.matcher(value);
while (matcher.find()) {
   String varName = matcher.group(1);
   String varValue;
   try {
       varValue = props.getProperty(varName);
   } catch (MissingResourceException e) {
       varValue = varName; // Set unmatched variable to its name
   }
   result = result.replace(varName, varValue);
}
return result;
}

