/**
 * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
 * @param desiredCapacity the capacity desired by the user.
 * @return the capacity which should be used for a hashtable.
 */
public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    if (desiredCapacity > 1000) {
        // If the desired capacity is over 1000, we can use the 11% rule as a first approximation
        desiredCapacity = (int)Math.ceil(desiredCapacity * 1.11);
    }

    // Knuth's algorithm to find the next prime number
    int n = desiredCapacity | 1;
    int i = 0;
    while (true) {
        int m = n - 1;
        int s = 0;
        while (m % 2 == 0) {
            m /= 2;
            s++;
        }
        for (int r = 3; r <= Math.sqrt(n); r += 2) {
            while (m % r == 0) {
                m /= r;
                s++;
            }
        }
        if (m > 1) {
            s += 2;
        }
        if (s >= i) {
            n += 2;
            i = s;
        } else {
            return n;
        }
    }
}

