protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize an empty graph path
    GraphPath<V,E> path = new GraphPath<>();

    // Iterate over the edges in the set
    for (E edge : tour) {
        // Get the edge's incident vertices
        V incidentVertex1 = graph.getEdgeSource(edge);
        V incidentVertex2 = graph.getEdgeTarget(edge);

        // Add the edge to the graph path
        path.addEdge(incidentVertex1, incidentVertex2);
    }

    // Return the graph path
    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>();
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("The tour or graph cannot be null");
    } else if (tour.size() == 0) {
        throw new IllegalArgumentException("The tour cannot be empty");
    } else if (!graph.containsAll(tour)) {
        throw new IllegalArgumentException("The tour does not contain all edges");
    } else {
        Iterator<E> itr = tour.iterator();
        E edge = itr.next();
        path.add(edge.source());
        path.add(edge.destination());
        while (itr.hasNext()) {
            edge = itr.next();
            path.add(edge.source());
            path.add(edge.destination());
        }
    }
    return path;
}

