private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Create a new list to store the suffix sum
    List<Integer> suffixSumList = new ArrayList<>();

    // Dictionary to store the count of each integer in the original list
    Map<Integer, Integer> countMap = new HashMap<>();

    // Loop through the original list and increment the count of each integer in the dictionary
    for (int bound : bounds) {
        if (countMap.containsKey(bound)) {
            countMap.put(bound, countMap.get(bound) + 1);
        } else {
            countMap.put(bound, 1);
        }
    }

    // Loop through the dictionary and calculate the suffix sum for each integer
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int currentSum = 0;
        for (int j = i; j < bounds.size(); j++) {
            currentSum += countMap.get(bounds.get(j));
        }
        suffixSumList.add(currentSum);
    }

    // Return the list of suffix sums and the sum of all elements in the original list
    return new Pair<>(suffixSumList, Arrays.stream(bounds.toArray()).sum());
}
