private void ensureCapacity(final int size){
    int currentCapacity = data.length - position;
    if(size > currentCapacity) {
        int newCapacity = calculateNewCapacity(currentCapacity, size);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, data.length);
        data = newData;
    }
}

private int calculateNewCapacity(final int currentCapacity, final int size){
    return Math.max(16, currentCapacity + size);
}

private void writeInt(final int value){                  
    int temp = value;
    for(int i = 0; i < Field.INT_BYTES; i++){                  
        byte writeB = (temp & Field.INT_MASK);                              
        data[position+i] = writeB;                             
        temp = temp >>> Field.BYTE_BITS;                       
    }
    position += Field.INT_BYTES;                               
}

