public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the input graph and set of vertices are valid
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and set of vertices must be non-null and non-empty");
    }

    // Create a new set to store the neighbor vertices of each vertex in the subgraph
    Set<V> neighborVertices = new HashSet<>();

    // Iterate over each vertex in the subgraph
    for (V vertex : vertices) {
        // Get the neighbor vertices of the current vertex
        neighborVertices.addAll(graph.getNeighbors(vertex));
    }

    // Return true if the subgraph is a clique, i.e. the intersection of the neighbor vertices and the subgraph vertices is the same as the subgraph vertices
    return vertices.size() == neighborVertices.size() && neighborVertices.containsAll(vertices);
}

