            else if (line.startsWith("++")) {
                ThreadSnapshot threadSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                threadSnapshot.setEndTime(Long.valueOf(line.split(" ")[1]));
            }
            // If the line contains a timestamp and a method name, add a method stack trace to the current thread snapshot
            else if (line.contains(".()")) {
                ThreadSnapshot threadSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                String[] tokens = line.split(" ");
                long timestamp = Long.valueOf(tokens[0]);
                String methodName = tokens[2].substring(0, tokens[2].length() - 1);
